<script>
  /**
   * @typedef {"mini" | "2xs" | "xs" | "sm" | "md" | "lg" | "xl"} AILabelSize
   * @event revert
   * @type {null}
   * @slot {{}}
   * @slot {{}} actions
   */

  /**
   * AILabel marks AI-generated content. Its button opens a callout that
   * explains how AI was used; put the explanation in the default slot and
   * optional buttons in the `actions` slot.
   *
   * @example
   * ```svelte
   * <AILabel>
   *   <Text type="label-01">AI explained</Text>
   *   <Text>This summary was generated by a model.</Text>
   * </AILabel>
   * ```
   */

  /**
   * Specify the size. `kind="inline"` uses `sm`, `md`, or `lg`.
   * @type {AILabelSize}
   */
  export let size = "xs";

  /**
   * Specify the kind. `"inline"` renders the AI text without a box, for
   * labels that sit next to text.
   * @type {"default" | "inline"}
   */
  export let kind = "default";

  /** Specify the text in the button */
  export let aiText = "AI";

  /**
   * Specify text shown after the AI text. Only used with `kind="inline"`.
   */
  export let textLabel = "";

  /**
   * Specify the button's accessible description, read after the AI text.
   */
  export let iconDescription = "Show information";

  /**
   * Set to `true` to replace the label with a button that reverts an
   * AI-generated value. Clicking it dispatches `revert`.
   */
  export let revertActive = false;

  /** Specify the revert button's label */
  export let revertLabel = "Revert to AI input";

  /**
   * Set the callout's alignment relative to the button.
   * @type {"start" | "center" | "end"}
   */
  export let align = "start";

  /**
   * Set the callout's direction relative to the button.
   * @type {"top" | "bottom" | "left" | "right"}
   */
  export let direction = "bottom";

  /**
   * Set to `true` to open the callout.
   * @bindable
   */
  export let open = false;

  /**
   * Set an id for the callout's toggletip.
   * @type {string | undefined}
   */
  export let id = undefined;

  /**
   * Obtain a reference to the button element.
   * @type {null | HTMLButtonElement}
   */
  export let ref = null;

  import { createEventDispatcher, setContext } from "svelte";
  import Button from "../Button/Button.svelte";
  import Undo from "../icons/Undo.svelte";
  import Toggletip from "../Toggletip/Toggletip.svelte";
  import { splitAriaNaming } from "../utils/aria-naming.js";

  const dispatch = createEventDispatcher();

  setContext("carbon:AILabel", true);

  // Naming and description go to the button (through Toggletip); the rest
  // stays on the wrapper.
  $: ({ ariaLabel, ariaLabelledBy, ariaDescribedBy, rest } =
    splitAriaNaming($$restProps));

  $: inline = kind === "inline";
  $: withContent = inline && !!textLabel;
</script>

{#if revertActive}
  <span class:bx--ai-label={true} class:bx--ai-label--revert={true} {...rest}>
    <Button
      kind="ghost"
      size="small"
      iconOnly
      icon={Undo}
      iconDescription={revertLabel}
      on:click={() => dispatch("revert")}
    />
  </span>
{:else}
  <span
    class:bx--ai-label={true}
    class="bx--ai-label--{size}"
    class:bx--ai-label--inline={inline}
    class:bx--ai-label--inline-with-content={withContent}
    {...rest}
  >
    <Toggletip
      {...id === undefined ? {} : { id }}
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledBy}
      aria-describedby={ariaDescribedBy}
      bind:open
      bind:ref
      {align}
      {direction}
      iconDescription="{aiText} {textLabel || iconDescription}"
      on:open
      on:close
    >
      <svelte:fragment slot="icon">
        <span class:bx--ai-label__text={true}>{aiText}</span>
        {#if withContent}
          <span class:bx--ai-label__additional-text={true}>{textLabel}</span>
        {/if}
      </svelte:fragment>
      <div
        class:bx--ai-label-content={true}
        class:bx--ai-label-content--with-actions={$$slots.actions}
      >
        <slot />
      </div>
      {#if $$slots.actions}
        <div class:bx--ai-label-actions={true}>
          <slot name="actions" />
        </div>
      {/if}
    </Toggletip>
  </span>
{/if}
